custody.py.text:
"""Custody check for TASK-20261002-ab21d1 (VA4-1, J2 item vii).

Own code. Reads committed bytes with `git show <ref>:<path>` one path at a
time, hashes with hashlib.sha256, compares with each snapshot receipt's
path_sha256. Also hashes the working-tree file and lists every commit that
touched each path (custody history only).
"""
import hashlib
import json
import subprocess
import sys

REPO = "/home/user/crypto-autoresearcher"
RECEIPTS = {
    "v4": ("TASK-20261002-c21ce2",
           "coordination/goals/GOAL-ECDLP2M-001/batches/BATCH-f6b7c5/archives/TASK-20261002-c21ce2/snapshot-receipt.json"),
    "v3": ("TASK-20260929-76139a",
           "coordination/goals/GOAL-ECDLP2M-001/batches/BATCH-35bdda/archives/TASK-20260929-76139a/snapshot-receipt.json"),
    "v2": ("TASK-20260929-36a146",
           "coordination/goals/GOAL-ECDLP2M-001/batches/BATCH-361e02/archives/TASK-20260929-36a146/snapshot-receipt.json"),
    "v1": ("TASK-20260928-7a6424",
           "coordination/goals/GOAL-ECDLP2M-001/batches/BATCH-d34db1/archives/TASK-20260928-7a6424/snapshot-receipt.json"),
}
REFS = ["HEAD", "origin/main"]
SNAP_V4 = "c29ca56724e96ce620ef44975f045bbb083fd112"


def git(*args):
    return subprocess.run(["git", "-C", REPO, *args], check=True,
                          capture_output=True).stdout


def sha_at(ref, path):
    try:
        return hashlib.sha256(git("show", f"{ref}:{path}")).hexdigest()
    except subprocess.CalledProcessError as exc:
        return "MISSING: " + exc.stderr.decode().strip()


def sha_worktree(path):
    try:
        with open(f"{REPO}/{path}", "rb") as fh:
            return hashlib.sha256(fh.read()).hexdigest()
    except OSError as exc:
        return f"MISSING: {exc}"


out = {"head": git("rev-parse", "HEAD").decode().strip(),
       "origin_main": git("rev-parse", "origin/main").decode().strip(),
       "versions": {}}
all_ok = True
for ver, (task, rpath) in RECEIPTS.items():
    receipt = json.loads(git("show", f"HEAD:{rpath}"))
    assert receipt["task_id"] == task, (receipt["task_id"], task)
    rows = {}
    refs = REFS + ([SNAP_V4] if ver == "v4" else [])
    for path, expected in receipt["path_sha256"].items():
        row = {"expected": expected}
        for ref in refs:
            row[ref] = sha_at(ref, path)
        row["worktree"] = sha_worktree(path)
        row["match_all"] = all(row[k] == expected for k in refs + ["worktree"])
        row["commits_touching"] = git(
            "log", "--format=%H %s", "--", path).decode().strip().splitlines()
        all_ok &= row["match_all"]
        rows[path] = row
    out["versions"][ver] = {"receipt": rpath, "task": task,
                            "binding_mode": receipt.get("binding_mode"),
                            "files": rows}
out["all_match"] = all_ok
json.dump(out, sys.stdout, indent=1)
print()

j1_dcarry.py.text:
"""J1 (vi) D-CARRY. ONE script, applied identically to the version-3 audit
sheet (bound by TASK-20260929-76139a, read at 09d9c1aa548d) and the version-4
audit sheet (bound by TASK-20261002-c21ce2, read at c29ca56724). Extracts:
  (a) the constants block and its v3 additions, leaf by leaf;
  (b) design_figures and design_figures_v3_additions, leaf by leaf (these hold
      every Q1 to Q7 design figure: Q1 log2 B_cap; Q2 T_gen, P_gen; Q3
      identity and LA; Q4 the m = 5 window; Q5 rho; Q6 the m = 4 slices and
      envelope; Q7 the L = 1 slices);
  (c) every module-level literal of stage0_code (the DESIGN table included),
      by ast.literal_eval of the module-level assignments;
  (d) every occurrence of the committed m = 4 range in the sheet text.
and diffs them value by value. Never reads the carried J5 report.
"""
import ast
import hashlib
import json
import re
import subprocess
import sys

import yaml

REPO = "/home/user/crypto-autoresearcher"
SHEETS = {
    "v3": ("09d9c1aa548d9f02469f02f393279132a6c01966",
           "coordination/goals/GOAL-ECDLP2M-001/batches/BATCH-35bdda/design/TASK-20260929-6f5e6d/proof-search-map-audit.yaml",
           "1f430d426b698971753ea807ac80bc0198b598ca1c782914095d8a1b0898cc1a"),
    "v4": ("c29ca56724e96ce620ef44975f045bbb083fd112",
           "coordination/goals/GOAL-ECDLP2M-001/batches/BATCH-f6b7c5/design/TASK-20261002-b75ae9/proof-search-map-audit.yaml",
           "969177f945216a0f592d86f2d66078465393a90e28daffdcefde8a312050996f"),
}
BLOCKS = ["constants", "constants_v3_additions", "design_figures", "design_figures_v3_additions"]
RANGE_PAT = re.compile(r"29\.036035|35\.996035|\b697\b|M4_RANGE|M4_STEP|M4_POINTS")


def flatten(x, prefix=""):
    out = {}
    if isinstance(x, dict):
        for k, v in x.items():
            out.update(flatten(v, f"{prefix}.{k}" if prefix else str(k)))
    elif isinstance(x, list):
        for i, v in enumerate(x):
            out.update(flatten(v, f"{prefix}[{i}]"))
    else:
        out[prefix] = x
    return out


def stage0_literals(code):
    tree = ast.parse(code)
    lits = {}
    for st in tree.body:
        if isinstance(st, ast.Assign) and len(st.targets) == 1 and isinstance(st.targets[0], ast.Name):
            try:
                lits[st.targets[0].id] = ast.literal_eval(st.value)
            except ValueError:
                lits[st.targets[0].id] = "<non-literal: " + ast.unparse(st.value) + ">"
    return lits


def extract(ver):
    commit, path, want = SHEETS[ver]
    raw = subprocess.run(["git", "-C", REPO, "show", f"{commit}:{path}"],
                         check=True, capture_output=True).stdout
    assert hashlib.sha256(raw).hexdigest() == want, ver
    root = yaml.safe_load(raw.decode("utf-8"))["proof_search_map_audit"]
    leaves = {}
    for b in BLOCKS:
        for k, v in flatten(root.get(b, {}), b).items():
            leaves[k] = v
    lits = stage0_literals(root["stage0_code"])
    for k, v in flatten(lits, "stage0_code").items():
        leaves[k] = v
    text = raw.decode("utf-8").split("\n")
    range_lines = [ln.strip() for ln in text if RANGE_PAT.search(ln)]
    return leaves, range_lines


L3, R3 = extract("v3")
L4, R4 = extract("v4")
same = sorted(k for k in L3 if k in L4 and L3[k] == L4[k] and type(L3[k]) == type(L4[k]))
changed = sorted(k for k in L3 if k in L4 and (L3[k] != L4[k] or type(L3[k]) != type(L4[k])))
removed = sorted(k for k in L3 if k not in L4)
added = sorted(k for k in L4 if k not in L3)
res = {
    "leaves_v3": len(L3), "leaves_v4": len(L4),
    "identical": len(same),
    "changed": {k: {"v3": L3[k], "v4": L4[k]} for k in changed},
    "removed_in_v4": {k: L3[k] for k in removed},
    "added_in_v4": {k: L4[k] for k in added},
    "per_block_identical": {b: sum(1 for k in same if k.startswith(b + ".") or k.startswith(b + "["))
                            for b in BLOCKS + ["stage0_code"]},
    "per_block_total_v3": {b: sum(1 for k in L3 if k.startswith(b + ".") or k.startswith(b + "["))
                           for b in BLOCKS + ["stage0_code"]},
    "m4_range_lines_v3": R3, "m4_range_lines_v4": R4,
    "m4_range_lines_only_v3": [x for x in R3 if x not in R4],
    "m4_range_lines_only_v4": [x for x in R4 if x not in R3],
}
json.dump(res, sys.stdout, indent=1, default=str)
print()

j1_dcarry_qmap.py.text:
"""D-CARRY table by quantity group: every leaf of the v3 and v4 audit sheets'
constants, design_figures (and their v3 additions) and every stage0_code
literal, assigned to the Q1 to Q7 groups the plan names (Q1 B_cap; Q2 T_gen
and P_gen; Q3 identity and LA comparison; Q4 m = 5 window; Q5 rho; Q6 m = 4
slices and envelope; Q7 L = 1 ties) or to 'constants', 'm4_range' or 'other';
same extraction as j1_dcarry.py, value-by-value comparison."""
import ast, hashlib, json, subprocess, sys
import yaml
R = "/home/user/crypto-autoresearcher"
SH = {"v3": ("09d9c1aa548d9f02469f02f393279132a6c01966", "coordination/goals/GOAL-ECDLP2M-001/batches/BATCH-35bdda/design/TASK-20260929-6f5e6d/proof-search-map-audit.yaml"),
      "v4": ("c29ca56724e96ce620ef44975f045bbb083fd112", "coordination/goals/GOAL-ECDLP2M-001/batches/BATCH-f6b7c5/design/TASK-20261002-b75ae9/proof-search-map-audit.yaml")}
def flatten(x, p=""):
    o = {}
    if isinstance(x, dict):
        for k, v in x.items(): o.update(flatten(v, f"{p}.{k}" if p else str(k)))
    elif isinstance(x, list):
        for i, v in enumerate(x): o.update(flatten(v, f"{p}[{i}]"))
    else: o[p] = x
    return o
def leaves(ver):
    c, p = SH[ver]
    raw = subprocess.run(["git", "-C", R, "show", f"{c}:{p}"], capture_output=True, check=True).stdout
    root = yaml.safe_load(raw)["proof_search_map_audit"]
    out = {}
    for b in ("constants", "constants_v3_additions", "design_figures", "design_figures_v3_additions"):
        out.update(flatten(root.get(b, {}), b))
    lits = {}
    for st in ast.parse(root["stage0_code"]).body:
        if isinstance(st, ast.Assign) and isinstance(st.targets[0], ast.Name):
            try: lits[st.targets[0].id] = ast.literal_eval(st.value)
            except ValueError: pass
    out.update(flatten(lits, "stage0_code"))
    return out
RULES = [("Q1", ["design_figures.column.log2_B_cap", "stage0_code.DESIGN.log2_B_cap"]),
         ("Q2", ["design_figures.column.log2_T_gen", "design_figures.column.log2_P_gen", "stage0_code.DESIGN.log2_T_gen", "stage0_code.DESIGN.log2_P_gen"]),
         ("Q3", ["design_figures.column.identity_residual", "design_figures.column.log2_LA", "stage0_code.DESIGN.log2_LA"]),
         ("Q4", ["design_figures.m5_window_at_B_cap", "stage0_code.DESIGN.m5_", "stage0_code.G5", "stage0_code.PROP_5", "stage0_code.D3_5"]),
         ("Q5", ["constants.rho", "stage0_code.K_FROB", "stage0_code.R$"]),
         ("Q6", ["design_figures.m4_", "stage0_code.DESIGN.m4_sub", "stage0_code.DESIGN.m4_cap", "stage0_code.DESIGN.env_", "stage0_code.G4_", "stage0_code.X4_CAP", "stage0_code.X_SUB", "stage0_code.D3_4", "design_figures_v3_additions.comparator_memory_m4_cap_and_envelope"]),
         ("Q7", ["design_figures.l1_slices", "stage0_code.DESIGN.m4_L1", "stage0_code.DESIGN.m4_tie", "stage0_code.DESIGN.m5_L1", "stage0_code.DESIGN.m5_tie"]),
         ("m4_range", ["constants.m4_envelope_range", "stage0_code.M4_RANGE", "stage0_code.M4_STEP", "stage0_code.M4_POINTS", "design_figures.m4_envelope.range_log2_B", "design_figures.m4_envelope.points"]),
         ("constants", ["constants.", "constants_v3_additions."]),
         ("other_design_figures_and_stage0_literals", ["design_figures", "stage0_code."])]
def group(k):
    if k.startswith("stage0_code.DESIGN.m4_L1") or k.startswith("stage0_code.DESIGN.m4_tie"):
        return "Q7"
    for g, prefixes in RULES:
        if any((k == p[:-1]) if p.endswith("$") else k.startswith(p) for p in prefixes):
            if g == "Q6" and k.startswith("design_figures.m4_envelope.range_log2_B") or k.startswith("design_figures.m4_envelope.points"):
                return "m4_range"
            return g
    return "unassigned"
L3, L4 = leaves("v3"), leaves("v4")
tab = {}
for k in sorted(set(L3) | set(L4)):
    g = group(k)
    t = tab.setdefault(g, {"leaves_v3": 0, "leaves_v4": 0, "identical": 0, "different": [], "only_v3": [], "only_v4": []})
    if k in L3: t["leaves_v3"] += 1
    if k in L4: t["leaves_v4"] += 1
    if k in L3 and k in L4:
        if L3[k] == L4[k] and type(L3[k]) == type(L4[k]): t["identical"] += 1
        else: t["different"].append({"leaf": k, "v3": L3[k], "v4": L4[k]})
    elif k in L3: t["only_v3"].append(k)
    else: t["only_v4"].append(k)
json.dump(tab, sys.stdout, indent=1, default=str); print()

j2_code_diff.py.text:
"""J2 (ii): diff binstd_core between the version-3 and version-4 extractions
(hash-verified files in this scratch), top-level definition by definition,
with ast.dump (no line attributes). Classifies each name as unchanged,
docstring_only, changed, added or removed, and module-level assignments as
same, changed, added or removed; then compares with the audit sheet's
code_delta lists (read from the bound v4 sheet)."""
import ast
import json
import subprocess
import sys

import yaml

OUT = "/tmp/claude-0/-home-user/f42055f8-3588-569d-b7d9-926d696d2468/scratchpad/BATCH-f6b7c5/TASK-20261002-ab21d1"
REPO = "/home/user/crypto-autoresearcher"


def defs(path):
    tree = ast.parse(open(path, encoding="utf-8").read())
    fn, assigns, other = {}, {}, []
    for st in tree.body:
        if isinstance(st, (ast.FunctionDef, ast.ClassDef, ast.AsyncFunctionDef)):
            fn[st.name] = st
        elif isinstance(st, ast.Assign):
            names = ",".join(ast.unparse(t) for t in st.targets)
            assigns[names] = ast.unparse(st.value)
        else:
            other.append(ast.dump(st))
    return fn, assigns, other, tree


def strip_doc(node):
    n = ast.parse(ast.unparse(node)).body[0]
    for sub in ast.walk(n):
        if isinstance(sub, (ast.FunctionDef, ast.ClassDef, ast.AsyncFunctionDef)):
            b = sub.body
            if b and isinstance(b[0], ast.Expr) and isinstance(getattr(b[0], "value", None), ast.Constant) \
                    and isinstance(b[0].value.value, str):
                sub.body = b[1:] or [ast.Pass()]
    return ast.dump(n)


f3, a3, o3, t3 = defs(f"{OUT}/v3_binstd_core.py")
f4, a4, o4, t4 = defs(f"{OUT}/v4_binstd_core.py")
cls = {"unchanged": [], "docstring_only": [], "changed": [], "added": [], "removed": []}
for name in sorted(set(f3) | set(f4)):
    if name not in f4:
        cls["removed"].append(name)
    elif name not in f3:
        cls["added"].append(name)
    elif ast.dump(f3[name]) == ast.dump(f4[name]):
        cls["unchanged"].append(name)
    elif strip_doc(f3[name]) == strip_doc(f4[name]):
        cls["docstring_only"].append(name)
    else:
        cls["changed"].append(name)
asg = {"same": [], "changed": {}, "added": {}, "removed": {}}
for k in sorted(set(a3) | set(a4)):
    if k not in a4:
        asg["removed"][k] = a3[k]
    elif k not in a3:
        asg["added"][k] = a4[k]
    elif a3[k] == a4[k]:
        asg["same"].append(k)
    else:
        asg["changed"][k] = {"v3": a3[k], "v4": a4[k]}
mod_doc_same = ast.get_docstring(t3) == ast.get_docstring(t4)

raw = subprocess.run(["git", "-C", REPO, "show",
                      "c29ca56724e96ce620ef44975f045bbb083fd112:coordination/goals/GOAL-ECDLP2M-001/batches/BATCH-f6b7c5/design/TASK-20261002-b75ae9/proof-search-map-audit.yaml"],
                     check=True, capture_output=True).stdout
cd = yaml.safe_load(raw)["proof_search_map_audit"]["code_delta"]
claimed = {"unchanged": set(cd["unchanged_body"]),
           "docstring_only": set(cd["docstring_only"]),
           "changed": {r["function"] for r in cd["changed"]},
           "added": set(cd["added"]),
           "removed": set(cd["removed"])}
cmp = {}
for k in cls:
    got = set(cls[k])
    cmp[k] = {"mine_count": len(got), "claimed_count": len(claimed[k]),
              "in_mine_not_claimed": sorted(got - claimed[k]),
              "in_claimed_not_mine": sorted(claimed[k] - got)}
# where do my 'changed' land in the claimed lists?
misplaced = {}
for k, names in cls.items():
    for n in names:
        homes = [c for c, s in claimed.items() if n in s]
        if homes != [k]:
            misplaced[n] = {"mine": k, "claimed": homes}
json.dump({"classification": cls, "assignments": asg, "module_docstring_same": mod_doc_same,
           "other_module_level_v3": len(o3), "other_module_level_v4": len(o4),
           "other_module_level_same": o3 == o4,
           "vs_code_delta": cmp, "misplaced": misplaced}, sys.stdout, indent=1)
print()

j2_changed_functions.py.text:
"""Unified diff (2 context lines) of every changed and docstring-only function
of binstd_core, v3 against v4 (hash-verified extractions), plus any differing
non-def module-level statement."""
import ast, difflib, json
S = "/tmp/claude-0/-home-user/f42055f8-3588-569d-b7d9-926d696d2468/scratchpad/BATCH-f6b7c5/TASK-20261002-ab21d1"
def src_map(p):
    s = open(p, encoding="utf-8").read(); t = ast.parse(s); m = {}
    for st in t.body:
        if isinstance(st, (ast.FunctionDef, ast.ClassDef)):
            m[st.name] = ast.get_source_segment(s, st)
    others = [ast.get_source_segment(s, st) for st in t.body
              if not isinstance(st, (ast.FunctionDef, ast.ClassDef, ast.Assign))]
    return m, others
m3, o3 = src_map(f"{S}/v3_binstd_core.py"); m4, o4 = src_map(f"{S}/v4_binstd_core.py")
d = json.load(open(f"{S}/j2_code_diff.out.json"))
for name in d["classification"]["changed"] + d["classification"]["docstring_only"]:
    ud = list(difflib.unified_diff(m3[name].splitlines(), m4[name].splitlines(),
                                   f"v3:{name}", f"v4:{name}", lineterm="", n=2))
    print("\n".join(ud) + "\n")
for a, b in zip(o3, o4):
    if a != b:
        print("--- module-level non-def statement differs (first 100 chars) v3:", repr(a[:100]), "| v4:", repr(b[:100]))

